mapper.select:
SELECT * FROM ( SELECT FROM CLINICAL_TRIAL WHERE SOURCE_TYPE = 'API' AND REVIEW_STATUS = 'APPROVED'
AND ( LOWER(TITLE) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(OFFICIAL_TITLE) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(NCT_ID) LIKE '%' || LOWER(#{keyword}) || '%' )
AND RECRUITMENT_STATUS = #{recruitmentStatus}
ORDER BY NVL(UPDATED_AT, CREATED_AT) DESC ) WHERE ROWNUM <= #{limit}

SELECT * FROM ( SELECT T.TRIAL_NO, T.NCT_ID, T.BUSINESS_NO, T.SOURCE_TYPE, T.TITLE, T.OFFICIAL_TITLE, T.BRIEF_SUMMARY, T.PHASE, T.STUDY_TYPE, T.RECRUITMENT_STATUS, T.ELIGIBILITY_TEXT, T.SEX, T.MIN_AGE, T.MAX_AGE, T.ENROLLMENT_TARGET, T.ENROLLMENT_CURRENT, T.LEAD_SPONSOR, T.INSTITUTION_NAME, T.LOCATION_TEXT, T.CONTACT_NAME, T.CONTACT_PHONE, T.CONTACT_EMAIL, T.START_DATE_TEXT, T.COMPLETION_DATE_TEXT, T.REVIEW_STATUS, T.REJECT_REASON, T.VIEW_COUNT, T.CREATED_AT, T.UPDATED_AT, D.DISEASE_NAME AS CONDITIONS_TEXT FROM CLINICAL_TRIAL T LEFT JOIN TRIAL_DISEASE TD ON TD.TRIAL_NO = T.TRIAL_NO LEFT JOIN DISEASE D ON D.DISEASE_NO = TD.DISEASE_NO WHERE T.SOURCE_TYPE = 'BUSINESS' AND T.REVIEW_STATUS = 'APPROVED'
AND ( LOWER(T.TITLE) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(T.OFFICIAL_TITLE) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(D.DISEASE_NAME) LIKE '%' || LOWER(#{keyword}) || '%' )
AND T.RECRUITMENT_STATUS = #{recruitmentStatus}
ORDER BY NVL(T.UPDATED_AT, T.CREATED_AT) DESC, T.TRIAL_NO DESC ) WHERE ROWNUM <= #{limit}
